<template><view class="room"><view class="top"><text @tap="back">×</text><text>直播间 · {{name}}</text><text>♡ 关注</text></view><view class="center"><view class="orb">LIVE</view><b>{{name}}的直播间</b><p>正在分享生活中的美好时刻</p><view class="enter">欢迎来到直播间</view></view><view class="bottom"><input v-model="msg" placeholder="和主播聊聊天..."/><text @tap="send">发送</text><text>♡</text><text>礼物</text></view><view v-if="tip" class="tip">{{tip}}</view></view></template><script setup>import{ref}from'vue';const name=ref('柒'),msg=ref(''),tip=ref('');function back(){uni.navigateBack()}function send(){tip.value=msg.value?'演示直播间暂未接入实时互动服务':'请输入内容';msg.value='';setTimeout(()=>tip.value='',1800)}</script><style scoped lang="scss">.room{height:100vh;color:white;background:radial-gradient(ellipse at 50% 35%,#67557e,#272337 58%,#171622);display:flex;flex-direction:column;justify-content:space-between;padding:24px 18px;box-sizing:border-box}.top,.bottom{display:flex;align-items:center;justify-content:space-between;font-size:13px}.top text:first-child{font-size:28px}.center{text-align:center;margin-top:-40px}.orb{width:112px;height:112px;border-radius:50%;margin:0 auto 26px;display:grid;place-items:center;border:1px solid #ffffff88;box-shadow:0 0 45px #d88cdb88;color:#f4b9ed;letter-spacing:4px}.center b{font-size:22px}.center p{font-size:12px;color:#c2b9ce}.enter{display:inline-block;margin-top:30px;padding:12px 26px;border-radius:25px;background:#ffffff18;border:1px solid #ffffff55;font-size:12px}.bottom input{width:55%;height:38px;border-radius:20px;background:#ffffff20;padding:0 14px;color:white;font-size:12px}.bottom text{color:#f4c0e7}.tip{position:absolute;bottom:80px;left:20%;right:20%;text-align:center;background:#0008;padding:10px;border-radius:20px;font-size:12px}</style>